  const selected = { partyItemId: fast.id, version: fast.version, quantity: '7', requiredBy: day(5), reason: 'Native supply contract', deliveries: [{ quantity: '6', expectedDate: day(2) }, { quantity: '6', expectedDate: day(4) }] }
