  await h.command('wo.operation.start',{...start,workCentre:'Alternate A'},{error:'WORK_CENTER'})
  await h.command('wo.operation.start',{...start,workCentre:'Alternate B'},{error:'TOOLING'})
  await h.command('capacity.sequence',{id:bad.id,version:bad.version,tools:['Fixture'],initialFamily:'steel',changeovers:[{from:'steel',to:'wood',minutes:40,cleanupMinutes:10}],planningHourlyCost:'60',reason:'synthetic-larder-621 restore qualified fixture'})
  executing=await h.command('wo.operation.start',{...start,workCentre:'Alternate B'});assert.equal(executing.operationStates[0].workCentre,'Alternate B')
