test('Replenishment revises MOQ and uncertain lead bounds, explains dated coverage and USD cash, approves selected suggestions and retains rejected reasons',async t=>{
  const h=await installation();t.after(()=>h.close());const day=n=>new Date(Date.now()+n*86400000).toISOString().slice(0,10)
  const planner=await h.person('synthetic-larder-901@example.test','planner'),buyer=await h.person('synthetic-larder-902@example.test','buyer'),agent=await h.person('synthetic-larder-903@example.test','agent')
  const loc=await h.command('location.save',{name:'synthetic-larder-904 supply bin'})
  const items=[]
  for(let i=0;i<2;i++)items.push(await h.command('item.save',{sku:`synthetic-larder-905-${i}`,name:'Replenishment alloy '+i,kind:'buy',baseUnit:'each',catalogLocations:i?[{locationId:loc.id,safetyStock:'2',minStock:'2',reorderPoint:'2'}]:[]}))
  const vendors=[];for(let i=0;i<2;i++)vendors.push(await h.command('party.save',{name:`synthetic-larder-906-${i}`,kind:'supplier'}))
  const customer=await h.command('party.save',{name:'synthetic-larder-907 customer',kind:'customer'})
  await h.command('opening.record',{locationId:loc.id,countedOn:day(0),valuationBasis:'supplier-invoice',countedBy:'Owner',evidence:evidence('synthetic-larder-919 one historical unit'),lines:[{itemId:items[0].id,quantity:'1',unitCost:'2'}]})
  let historical=await h.command('so.quote',{customerId:customer.id,promiseDate:day(0),lines:[{itemId:items[0].id,quantity:'1',unitPrice:'9'}]});historical=await h.command('so.confirm',{orderId:historical.id,version:historical.version})
  let shipped=await h.command('shipment.pick',{orderId:historical.id,lines:[{lineId:historical.lines[0].id,locationId:loc.id,quantity:'1'}]});shipped=await h.command('shipment.pack',{shipmentId:shipped.id,version:shipped.version,packages:1});shipped=await h.command('shipment.ship',{shipmentId:shipped.id,version:shipped.version,carrier:'Recorded collection'})
  let order=await h.command('so.quote',{customerId:customer.id,promiseDate:day(10),lines:items.map(i=>({itemId:i.id,quantity:'7',unitPrice:'9'}))});order=await h.command('so.confirm',{orderId:order.id,version:order.version,reserve:false})
  const base={partyCode:'synthetic-larder-908',packQuantity:'6',moq:'6',leadDays:1,leadDaysMax:2,weekdays:[0,1,2,3,4,5,6],closedDates:[day(1)],currency:'CAD',usdRate:'0.75',rateOn:day(0),rateSource:'synthetic-larder-909 recorded quote',price:'2',breaks:[{quantity:'12',price:'1.6'}],paymentTerms:'Net 30',freightTerms:'Delivered'}
  let terms=await h.command('supplier.terms',{...base,partyId:vendors[0].id,itemId:items[0].id})
  await h.command('supplier.terms',{...base,partyId:vendors[1].id,itemId:items[0].id,partyCode:'synthetic-larder-910',leadDaysMax:15})
  await h.command('supplier.terms',{...base,partyId:vendors[0].id,itemId:items[1].id,partyCode:'synthetic-larder-911'})
  await h.command('supplier.terms',{...base,partyId:vendors[0].id,itemId:items[0].id,id:terms.id,version:terms.version,leadDaysMax:0},{error:'INPUT'})
  const monday=new Date(day(14)+'T00:00Z');monday.setUTCDate(monday.getUTCDate()-(monday.getUTCDay()+6)%7)
  await h.command('forecast.import',{stateVersion:(await h.state()).version,file:{name:'synthetic-larder-912.csv',content:`sku,week,quantity,seasonality\n${items[0].sku},${monday.toISOString().slice(0,10)},3,1`},reason:'synthetic-larder-913 forecast confidence review'})
  const preview=()=>planner.run('replenishment.preview',{itemIds:items.map(i=>i.id),horizonDays:60,historyDays:90,confidence:75,confidenceBasis:'synthetic-larder-914 planner assessment; sparse history disclosed',reason:'synthetic-larder-915 restock selected items'})
  const first=await preview();terms=await h.command('supplier.terms',{...base,partyId:vendors[0].id,itemId:items[0].id,id:terms.id,version:terms.version,moq:'18',leadDaysMax:4})
  const decisions=p=>p.rows.map(r=>({itemId:r.itemId,partyItemId:r.itemId===items[0].id?terms.id:null,reason:r.itemId===items[0].id?'synthetic-larder-916 selected conservative supplier':'synthetic-larder-917 defer discretionary reserve'}))
  await buyer.run('replenishment.approve',{planId:first.id,version:first.version,decisions:decisions(first)},{error:'STALE'})
  const plan=await preview(), a=plan.rows.find(r=>r.itemId===items[0].id),b=plan.rows.find(r=>r.itemId===items[1].id),fast=a.quotes.find(q=>q.partyItemId===terms.id),slow=a.quotes.find(q=>q.supplierId===vendors[1].id)
  assert.deepEqual([plan.confidence,fast.quantity,fast.latestDate,fast.price,fast.exposure],[75,'18',day(5),'1.6','21.6'])
  assert.equal(fast.covered,a.shortage);assert.equal(fast.atRisk,'0');assert.equal(fast.robustFeasible,true);assert.equal(slow.robustFeasible,false);assert.ok(Number(slow.atRisk)>0)
  assert.equal(a.forecasts.length,1);assert.equal(a.history.length,1);assert.deepEqual([a.history[0].shipmentId,a.history[0].quantity,a.history[0].netShippedQuantity],[shipped.id,'1','1']);assert.equal(b.history.length,0,'missing demand history stays explicit');assert.equal(b.safetyRequirements.length,1);assert.equal(b.safetyRequirements[0].shortage,'2')
  assert.equal((await h.state()).purchaseOrders.length,0,'review creates no purchase')
  await agent.run('replenishment.approve',{planId:plan.id,version:plan.version,decisions:decisions(plan)},{error:'FORBIDDEN'})
  await planner.run('replenishment.approve',{planId:plan.id,version:plan.version,decisions:decisions(plan)},{error:'FORBIDDEN'})
  await buyer.run('replenishment.approve',{planId:plan.id,version:plan.version,decisions:decisions(plan).slice(0,1)},{error:'INPUT'})
  await buyer.run('replenishment.approve',{planId:plan.id,version:plan.version,decisions:decisions(plan).map(d=>d.itemId===items[0].id?{...d,partyItemId:slow.partyItemId}:d)},{error:'INFEASIBLE_QUOTE'})
  const before=await h.state(),result=await buyer.run('replenishment.approve',{planId:plan.id,version:plan.version,decisions:decisions(plan)},{commandId:'synthetic-larder-918-approval'})
  assert.equal(result.documents.length,1);assert.equal(result.approvedCashExposure,'21.6');assert.equal(result.decisions.find(d=>d.itemId===items[1].id).reason,'synthetic-larder-917 defer discretionary reserve')
  const s=await h.state(),po=s.purchaseOrders.find(p=>p.id===result.documents[0].poId);assert.equal(po.status,'approved');assert.equal(po.expectedDate,day(5));assert.equal(po.lines[0].quantity,'18');assert.deepEqual(po.replenishment.quote,fast)
  assert.deepEqual(s.movements,before.movements);assert.deepEqual(s.reservations,before.reservations);assert.deepEqual(s.salesOrders,before.salesOrders)
  assert.deepEqual(await buyer.run('replenishment.approve',{planId:plan.id,version:plan.version,decisions:decisions(plan)},{commandId:'synthetic-larder-918-approval'}),result)
  await h.restart();assert.deepEqual((await h.state()).replenishmentPlans.find(p=>p.id===result.id),result)
  const a1=await(await h.request('/api/larder/archive')).json(),target=await installation();t.after(()=>target.close());assert.equal((await target.request('/api/larder/archive/restore',{method:'POST',body:a1})).status,200)
  const a2=await(await target.request('/api/larder/archive')).json();assert.deepEqual(a2.records.replenishmentPlans,a1.records.replenishmentPlans);assert.deepEqual(a2.records.purchaseOrders,a1.records.purchaseOrders);assert.match(await(await h.request('/api/larder/archive.csv')).text(),/replenishmentPlans/)
})

test('Bounded grants independently authorize one internal reflow, stop at limits or lost authority, and restore inactive without replay',async t=>{
  const h=await installation();t.after(()=>h.close());const w=await workshop(h),owner=(await h.state()).actor
  const planner=await h.person('synthetic-larder-951@example.test','planner'),reviewer=await h.person('synthetic-larder-952@example.test','manager'),agent=await h.person('synthetic-larder-953@example.test','agent')
  const start='2026-11-25T00:00:00Z'
  const machine=await h.command('capacity.machine',capacityCalendar('Grant bench'))
  await h.command('capacity.labor',capacityCalendar('Grant operator',{operatorIds:[owner.id],skills:[]}))
  await h.command('bom.revise',{itemId:w.board.id,components:[{itemId:w.timber.id,quantity:'1'}],routing:[{name:'Grant cut',workCentre:'Grant bench',minutes:120},{name:'Buffered finish',workCentre:'Grant bench',minutes:30,queueMinutes:15}]})
  const jobs=[]
  for(let i=0;i<3;i++){let job=await h.command('wo.draft',{itemId:w.board.id,quantity:'1',requiredBy:'2026-12-05',reason:'synthetic-larder-954 internal work'});job=await h.command('wo.release',{workOrderId:job.id,version:job.version});jobs.push(job)}
  let job=await h.command('wo.operation.assign',{workOrderId:jobs[0].id,version:jobs[0].version,sequence:1,operatorId:owner.id})
  job=await h.command('wo.operation.start',{workOrderId:job.id,version:job.version,sequence:1,workCentre:'Grant bench',station:'synthetic-larder-955 tablet',reason:'synthetic-larder-956 started work'})
  await h.command('order.rank',{kind:'work',orderId:jobs[2].id,version:jobs[2].version,rank:1})
  let protection=await planner.run('schedule.protect',{asOf:start,days:14,freezeUntil:start,manualLocks:[],reason:'synthetic-larder-957 explicit unfrozen window'})
  const args={eventTypes:['progress','breakdown','priority','ETA'],machineIds:[machine.id],workOrderIds:[],maxDelayMinutes:1440,maxDisplacementMinutes:1440,expiresAt:new Date(Date.now()+86400000).toISOString(),reason:'synthetic-larder-958 bounded grant'}
  for(const missing of ['eventTypes','machineIds','maxDelayMinutes','maxDisplacementMinutes','expiresAt']){const bad={...args};delete bad[missing];await planner.run('schedule.grant.prepare',bad,{error:'INPUT'})}
  let agentGrant=await agent.run('schedule.grant.prepare',args)
  await agent.run('schedule.grant.approve',{grantId:agentGrant.id,version:agentGrant.version,reason:'synthetic-larder-968 agent cannot authorize'},{error:'FORBIDDEN'})
  agentGrant=await h.command('schedule.grant.approve',{grantId:agentGrant.id,version:agentGrant.version,reason:'synthetic-larder-969 human approves agent preparation'})
  await agent.run('schedule.grant.revoke',{grantId:agentGrant.id,version:agentGrant.version,reason:'synthetic-larder-970 preparer withdraws own delegation'})
  let own=await h.command('schedule.grant.prepare',args)
  own=await h.command('schedule.grant.approve',{grantId:own.id,version:own.version,reason:'synthetic-larder-971 explicit owner exception'})
  await h.command('schedule.grant.revoke',{grantId:own.id,version:own.version,reason:'synthetic-larder-972 replace owner delegation'})
  let grant=await planner.run('schedule.grant.prepare',args)
  for(const actor of [planner,agent])await actor.run('schedule.grant.approve',{grantId:grant.id,version:grant.version,reason:'synthetic-larder-959 no self or agent approval'},{error:'FORBIDDEN'})
  grant=await reviewer.run('schedule.grant.approve',{grantId:grant.id,version:grant.version,reason:'synthetic-larder-960 independently bounded'})
  const before=await h.state(),pause={workOrderId:job.id,version:job.version,sequence:1,reason:'breakdown',note:'synthetic-larder-961 stop mid-job',escalationOwnerId:reviewer.id,anticipatedResumeAt:'2026-11-25T04:00:00Z'}
  const stopped=await h.send('wo.operation.pause',pause);assert.equal(stopped.body.ok,true)
  let s=await h.state(),plan=s.schedulePlans.find(p=>p.event?.commandId===stopped.commandId)
  assert.equal(plan.status,'adopted',plan.automation?.reason);assert.equal(plan.autoApplication.grantVersion,grant.version);assert.equal(plan.autoApplication.approverId,reviewer.id)
  assert.ok(plan.effects.some(e=>e.before!==e.after));assert.deepEqual(plan.autoApplication.before,plan.before.operations)
  assert.equal(plan.autoApplication.commandId,stopped.commandId);assert.deepEqual(plan.autoApplication.after,plan.after.operations)
  const old=plan.before.operations.find(o=>o.workOrderId===job.id&&o.sequence===1),active=plan.after.operations.find(o=>o.key===old.key)
  assert.equal(active.machineId,old.machineId);assert.equal(active.operatorId,old.operatorId)
  const successor=plan.after.operations.find(o=>o.workOrderId===job.id&&o.sequence===2);assert.ok(Date.parse(successor.startsAt)>=Date.parse(active.endsAt)+15*60000)
  for(const key of ['salesOrders','purchaseOrders','movements','reservations','machineCalendars','laborCalendars'])assert.deepEqual(s[key],before[key],key)
  assert.ok([...minuteOccupancy(plan.after.operations).values()].every(n=>n<=1))
  const bookings=s.scheduleBookings;await h.restart();await h.command('wo.operation.pause',pause,{commandId:stopped.commandId})
  s=await h.state();assert.deepEqual(s.scheduleBookings,bookings);assert.equal(s.schedulePlans.filter(p=>p.event?.commandId===stopped.commandId).length,1)
  const rank=async(force)=>{const current=(await h.state()).workOrders.find(w=>w.id===jobs[1].id);const sent=await h.send('order.rank',{kind:'work',orderId:current.id,version:current.version,rank:force??((current.rank??2)===1?2:1)});assert.equal(sent.body.ok,true);return (await h.state()).schedulePlans.find(p=>p.event?.commandId===sent.commandId)}
  const replace=async(overrides={})=>{grant=(await h.state()).scheduleGrants.find(g=>g.id===grant.id);grant=await planner.run('schedule.grant.prepare',{...args,id:grant.id,version:grant.version,...overrides});return grant}
  const approve=async()=>grant=await reviewer.run('schedule.grant.approve',{grantId:grant.id,version:grant.version,reason:'synthetic-larder-962 review exact revision'})
  await replace({maxDelayMinutes:0,maxDisplacementMinutes:0});const revisedBookings=(await h.state()).scheduleBookings
  plan=await rank();assert.equal(plan.status,'review');assert.deepEqual((await h.state()).scheduleBookings,revisedBookings)
  await approve();plan=await rank(1);assert.equal(plan.status,'review');assert.match(plan.automation.reason,/limit/);assert.deepEqual((await h.state()).scheduleBookings,revisedBookings)
  await replace({machineIds:[],workOrderIds:[job.id]});await approve();plan=await rank(1);assert.equal(plan.status,'review');assert.match(plan.automation.reason,/scope/);assert.deepEqual((await h.state()).scheduleBookings,revisedBookings)
  await replace();await approve();grant=await planner.run('schedule.grant.revoke',{grantId:grant.id,version:grant.version,reason:'synthetic-larder-963 preparer withdraws delegation'})
  plan=await rank();assert.equal(plan.status,'review');assert.deepEqual((await h.state()).scheduleBookings,revisedBookings)
  await replace();await approve()
  protection=await planner.run('schedule.protect',{version:protection.version,asOf:start,days:14,freezeUntil:start,manualLocks:[],reason:'synthetic-larder-964 protection revision suspends grant'})
  plan=await rank();assert.equal(plan.status,'review');assert.match(plan.automation.reason,/Protection/);assert.deepEqual((await h.state()).scheduleBookings,revisedBookings)
  await replace();await approve()
  await h.command('role.set',{operatorId:reviewer.id,role:'production'})
  plan=await rank();assert.equal(plan.status,'review');assert.match(plan.automation.reason,/approver/)
  assert.equal((await h.state()).scheduleGrants.find(g=>g.id===grant.id).status,'suspended')
  await h.command('role.set',{operatorId:reviewer.id,role:'manager'})
  plan=await rank();assert.equal(plan.status,'review');assert.deepEqual((await h.state()).scheduleBookings,revisedBookings)
  await replace();await approve()
  assert.equal((await h.request('/auth/operator/status',{method:'POST',body:{operatorId:reviewer.id,status:'inactive'}})).status,200)
  plan=await rank();assert.equal(plan.status,'review');assert.match(plan.automation.reason,/approver/);assert.deepEqual((await h.state()).scheduleBookings,revisedBookings)
  // A fresh live approval after expiry uses the owner exception; a recorded
  // expiry stops the next event, without an invented background clock.
  await replace({expiresAt:new Date(Date.now()+4000).toISOString()})
  grant=await h.command('schedule.grant.approve',{grantId:grant.id,version:grant.version,reason:'synthetic-larder-965 owner approval'})
  await new Promise(r=>setTimeout(r,Math.max(0,Date.parse(grant.expiresAt)-Date.now()+50)))
  plan=await rank();assert.equal(plan.status,'review');assert.match(plan.automation.reason,/expired/);assert.deepEqual((await h.state()).scheduleBookings,revisedBookings)
  await replace();grant=await h.command('schedule.grant.approve',{grantId:grant.id,version:grant.version,reason:'synthetic-larder-966 current owner approval'})
  const scenario=await h.command('schedule.scenario',{asOf:start,days:14,name:'Never automatic',reason:'synthetic-larder-967 isolated scenario'})
  assert.equal(scenario.status,'review');assert.deepEqual((await h.state()).scheduleBookings,revisedBookings)
  const lateBefore=(await h.state()).scheduleBookings,current=(await h.state()).workOrders.find(w=>w.id===job.id)
  const lateEvent=await h.send('wo.operation.progress',{workOrderId:current.id,version:current.version,sequence:1,completedQuantity:'0.5',remainingMinutes:16000,note:'synthetic-larder-985 actual remaining effort',reason:'synthetic-larder-986 supervisor estimate'})
  assert.equal(lateEvent.body.ok,true)
  const latePlan=(await h.state()).schedulePlans.find(p=>p.event?.commandId===lateEvent.commandId)
  assert.ok(latePlan.after.lateJobs.includes(job.id));assert.equal(latePlan.status,'review');assert.match(latePlan.automation.reason,/newly late/);assert.deepEqual((await h.state()).scheduleBookings,lateBefore)
  const archive=await(await h.request('/api/larder/archive')).json(),target=await installation();t.after(()=>target.close())
  assert.equal((await target.request('/api/larder/archive/restore',{method:'POST',body:archive})).status,200)
  const saved=await(await target.request('/api/larder/archive')).json(),restored=saved.records.scheduleGrants.find(g=>g.id===grant.id)
  assert.equal(restored.status,'draft');assert.equal(restored.approvedBy,null);assert.ok(restored.history.some(g=>g.status==='active'))
  assert.deepEqual(saved.records.schedulePlans,archive.records.schedulePlans);assert.deepEqual(saved.records.scheduleBookings,archive.records.scheduleBookings)
  assert.match(await(await h.request('/api/larder/archive.csv')).text(),/scheduleGrants/)
})

const costReport = async (h, name, query='', as) => {
  const res=await h.request(`/api/larder/costing/${name}${query}`,{as});assert.equal(res.status,200,await res.clone().text());return res.json()
}
async function zeroCostPolicy(h,overrides={}) {
  const p=await h.command('costing.policy.prepare',{standardLaborRate:'0',machineRate:'0',overheadRate:'0',overtimeAfterHours:'8',overtimeMultiplier:'1.5',reason:'synthetic-larder-401 explicit allocation rule',...overrides})
  return h.command('costing.policy.approve',{policyId:p.id,version:p.version,reason:'synthetic-larder-402 reviewed costing rule'})
}
async function costJob(h,item,location,quantity,issued,output,scrap='0',lot='synthetic-larder-403',clock=null) {
  let w=await h.command('wo.draft',{itemId:item.id,quantity,requiredBy:'2026-10-01',reason:'synthetic-larder-404 actual job'})
  w=await h.command('wo.release',{workOrderId:w.id,version:w.version})
  if(clock?.beforeIssue)await clock.beforeIssue()
  if(clock){let e=await h.command('time.start',{workOrderId:w.id,sequence:1,phase:'run'});const startedAt=new Date(Date.now()-clock.offset*3600000).toISOString(),stoppedAt=new Date(Date.parse(startedAt)+clock.hours*3600000).toISOString();e=await h.command('time.correct',{entryId:e.id,startedAt,stoppedAt,reason:'synthetic-larder-498 checked actual shift'});await h.command('time.decide',{entryId:e.id,correctionId:e.corrections[0].id,decision:'approve',reason:'synthetic-larder-499 approved actual time'})}
  if(issued.length)w=await h.command('wo.issue',{workOrderId:w.id,lines:issued})
  w=await h.command('wo.output',{workOrderId:w.id,version:w.version,locationId:location.id,quantity:output,scrap,scrapReason:'synthetic-larder-405 reject',lot})
  return h.command('wo.close',{workOrderId:w.id,version:w.version})
}

