  assert.equal(l.sources.find(x=>x.kind==='return').quantity,'-1');assert.equal(l.sources.find(x=>x.kind==='shipment').unitPrice,'89')
  await h.command('item.save',{id:w.board.id,version:w.board.version,sku:w.board.sku,name:w.board.name,kind:'make',baseUnit:'each',salePrice:'999',standardCost:'999'})
  assert.equal((await costReport(h,'margins',`?orderId=${o.id}`)).rows[0].quotedCost,'136.00')
  const csv=await(await h.request(`/api/larder/costing/margins.csv?orderId=${o.id}`)).text();assert.match(csv,/52.00/);assert.match(csv,/return/)
  const operator=await h.person('synthetic-larder-410@example.test','operator'),manager=await h.person('synthetic-larder-411@example.test','manager')
  for(const name of ['margins','margins.csv','variances','variances.csv','performance','performance.csv'])assert.equal((await h.request('/api/larder/costing/'+name,{as:operator.cookie})).status,403)
  await h.command('member.scope',{operatorId:manager.id,costsRestricted:true,locations:null})
  for(const as of [manager.cookie,operator.cookie])assert.equal((await h.request('/api/larder/attachments/'+commercial[0].evidence.id,{as})).status,403)
  assert.equal(await(await h.request('/api/larder/attachments/'+commercial[0].evidence.id)).text(),'synthetic-larder-407 invoice')
  const restricted=await costReport(h,'margins',`?orderId=${o.id}`,manager.cookie);assert.equal(restricted.rows[0].recognizedRevenue,'restricted');assert.equal(restricted.rows[0].actualMargin,'restricted');assert.equal(restricted.rows[0].sources[0].unitCost,'restricted')
  const hiddenCsv=await(await h.request(`/api/larder/costing/margins.csv?orderId=${o.id}`,{as:manager.cookie})).text();assert.match(hiddenCsv,/restricted/);assert.doesNotMatch(hiddenCsv,/52\.00|90\.00|38\.00/)
  const elsewhere=await h.command('location.save',{name:'synthetic-larder-521 hidden stock'})
  await h.command('opening.record',{locationId:elsewhere.id,countedOn:'2026-10-01',countedBy:'synthetic-larder-522',valuationBasis:'supplier-invoice',evidence:evidence(),lines:[{itemId:w.board.id,quantity:'1',unitCost:'77'}]})
  const hiddenOrder=await h.command('so.quote',{customerId:w.customer.id,promiseDate:'2026-11-01',lines:[{itemId:w.board.id,quantity:'1',unitPrice:'101'}]});await h.command('so.confirm',{orderId:hiddenOrder.id,version:hiddenOrder.version})
  let hiddenShip=await h.command('shipment.pick',{orderId:hiddenOrder.id,lines:[{lineId:hiddenOrder.lines[0].id,quantity:'1',locationId:elsewhere.id}]});hiddenShip=await h.command('shipment.pack',{shipmentId:hiddenShip.id,version:hiddenShip.version,packages:1});await h.command('shipment.ship',{shipmentId:hiddenShip.id,version:hiddenShip.version,carrier:'synthetic-larder-523'})
  await h.command('member.scope',{operatorId:manager.id,costsRestricted:false,locations:[w.loc.id]})
  const located=await costReport(h,'margins',`?orderId=${hiddenOrder.id}`,manager.cookie);assert.equal(located.rows[0].restricted,'restricted (includes other locations)');assert.equal(JSON.stringify(located).includes(elsewhere.id),false)
