  await h.command('opening.record', { locationId: location.id, countedOn: '2026-11-23', countedBy: 'Olive', valuationBasis: 'standard-cost', evidence: evidence(), lines: [{ itemId: raw.id, quantity: '3', unitCost: '10', lot: 'synthetic-larder-928-dated', dates: { manufacturedOn: '2026-11-01', expiresOn: '2026-11-29' } }] })
  let po = await h.command('po.draft', { supplierId: supplier.id, expectedDate: '2026-11-25', reason: 'Scarce material replenishment', lines: [{ itemId: raw.id, quantity: '10', unitPrice: '10' }] })
