  const owner = (await h.state()).people.find(person => person.role === 'owner')
  const definition = { name: 'Busy mill', timeZone: 'UTC', effectiveFrom: '2026-11-23', effectiveTo: '2026-12-31', shifts: [{ weekdays: [0, 1, 2, 3, 4, 5, 6], start: 480, end: 600 }], capacity: 1, efficiency: 100, reason: 'Recorded calendar' }
  await h.command('capacity.machine', definition)
